 public static void Validate(){var m=UnityEngine.Object.FindFirstObjectByType<VenueFinale>();string report="Venue upgrade saved geometry checks\n";var points=new[]{m.observeStand}.Concat(m.serviceRoute).ToArray();for(int i=1;i<points.Length;i++){var p=new NavMeshPath();bool ok=NavMesh.CalculatePath(points[i-1].position,points[i].position,NavMesh.AllAreas,p)&&p.status==NavMeshPathStatus.PathComplete;report+=(ok?"PASS ":"FAIL ")+points[i-1].name+" -> "+points[i].name+"\n";if(!ok){File.WriteAllText("Logs/Venue-upgrade-check.txt",report);throw new Exception(report);}}
 points=new[]{m.streetArrival}.Concat(m.alleyRoute).Concat(new[]{m.carStand}).ToArray();for(int i=1;i<points.Length;i++){var p=new NavMeshPath();bool ok=NavMesh.CalculatePath(points[i-1].position,points[i].position,NavMesh.AllAreas,p)&&p.status==NavMeshPathStatus.PathComplete;report+=(ok?"PASS ":"FAIL ")+points[i].name+" city route\n";if(!ok){File.WriteAllText("Logs/Venue-upgrade-check.txt",report);throw new Exception(report);}}File.WriteAllText("Logs/Venue-upgrade-check.txt",report);}
 static void Capture(Vector3 from,Vector3 at,string name){var g=new GameObject("Temporary venue camera");var cam=g.AddComponent<Camera>();var rt=new RenderTexture(1280,720,24);var previous=RenderTexture.active;try{cam.transform.position=from;cam.transform.LookAt(at);cam.fieldOfView=67;cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;var tex=new Texture2D(1280,720,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1280,720),0,0);tex.Apply();File.WriteAllBytes("Logs/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(g);}}

