 s+=$"entry {m.entry.position} turn {m.escapeTurn.position} car {m.carStand.position}\n";var path=new NavMeshPath();NavMesh.CalculatePath(m.entry.position,m.escapeTurn.position,NavMesh.AllAreas,path);s+="path "+path.status+" "+string.Join(" -> ",path.corners.Select(p=>p.ToString()))+"\n";
 foreach(var c in Physics.OverlapBox(new Vector3(12,2,75),new Vector3(18,3,55)))if(c.bounds.size.y>2)s+=c.name+" "+c.bounds+"\n";File.WriteAllText("Logs/Venue-upgrade-audit.txt",s);}
